const results=await Promise.allSettled([
tools.exec_command({cmd:"rg --files preparation -g '!recovery*/**' | rg '(목차|outline|method|extracted|3과목|subject3|README|AGENTS)' | Select-Object -First 65; Get-ChildItem -LiteralPath preparation -Name; Get-Content -LiteralPath preparation/eval/study_method_policy.json -Raw -Encoding UTF8",tty:true,login:false,workdir:"C:\\Users\\djliz\\study_certificate\\study_algorithm",max_output_tokens:5000}),
tools.exec_command({cmd:"python -c \"import fitz; d=fitz.open('src/target/3과목.pdf'); print('PAGES',len(d)); print('\\n'.join('PAGE '+str(i+1)+'\\n'+d[i].get_text() for i in range(min(9,len(d)))))\"; Get-ChildItem -LiteralPath src -Recurse -Filter '*.txt' | Where-Object { $_.Name -match '^01_책|^06_청킹|^21_책|^22_뼈대' } | ForEach-Object { $_.FullName; Get-Content -LiteralPath $_.FullName -Encoding UTF8 }",tty:true,login:false,workdir:"C:\\Users\\djliz\\study_certificate\\study_algorithm",max_output_tokens:12000})
]);results.forEach(text);

const r=await Promise.allSettled([
tools.exec_command({cmd:"Get-Content -LiteralPath C:/Users/djliz/.agents/skills/python-code-style/SKILL.md -Raw -Encoding UTF8; Get-Content -LiteralPath preparation/target_analysis/extracted/P3.json -Encoding UTF8 -TotalCount 15; Get-ChildItem 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe','C:/Program Files/Google/Chrome/Application/chrome.exe' -ErrorAction SilentlyContinue | Select-Object FullName",tty:true,login:false,workdir:"C:\\Users\\djliz\\study_certificate\\study_algorithm",max_output_tokens:4000}),
tools.exec_command({cmd:"python -m pip install --target preparation/pdf_tools reportlab pypdf pypdfium2 --disable-pip-version-check --quiet",tty:true,login:false,workdir:"C:\\Users\\djliz\\study_certificate\\study_algorithm",max_output_tokens:2000})
]);r.forEach(text);

