:root{
  --paper:#F2F4F1; --ledger:#DCE4E3; --ink:#16232E; --ink-soft:#4A5C68;
  --rule:#B9C6C6; --seal:#B0202E; --mark:#F5E06B; --ok:#2E6B4F; --add:#1F5C8B;
}
*{box-sizing:border-box;margin:0;padding:0}
html{-webkit-text-size-adjust:100%}
body{background:var(--paper);color:var(--ink);
  font-family:'Pretendard Variable',Pretendard,-apple-system,sans-serif;
  font-size:15px;line-height:1.75;
  padding:clamp(16px,4vw,56px) clamp(12px,4vw,24px);
  background-image:repeating-linear-gradient(180deg,transparent 0 31px,rgba(185,198,198,.28) 31px 32px);}
.sheet{max-width:900px;margin:0 auto;background:rgba(255,255,255,.72);border:1px solid var(--rule);
  box-shadow:0 1px 0 rgba(22,35,46,.06),0 18px 44px -32px rgba(22,35,46,.5);
  padding:clamp(20px,4.5vw,52px);}
.num{font-family:'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums;letter-spacing:-.01em}

/* header */
.head{border-bottom:2px solid var(--ink);padding-bottom:18px;margin-bottom:8px}
.eyebrow{font-family:'IBM Plex Mono',monospace;font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--ink-soft)}
h1{font-family:'Gowun Batang',serif;font-weight:700;font-size:clamp(23px,4.6vw,34px);line-height:1.3;margin:10px 0 4px;letter-spacing:-.02em}
.sub{font-size:14px;color:var(--ink-soft)}
.meta{margin-top:18px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px 22px;
  font-size:12.5px;border-top:1px solid var(--rule);padding-top:12px}
.meta div{display:flex;justify-content:space-between;gap:10px;border-bottom:1px dotted var(--rule);padding-bottom:4px}
.meta span:first-child{color:var(--ink-soft);white-space:nowrap}
.mark{background:linear-gradient(180deg,transparent 12%,var(--mark) 12% 88%,transparent 88%);padding:0 3px;font-weight:600}

/* sections */
section{margin-top:44px;scroll-margin-top:20px}
.sechead{display:flex;align-items:baseline;gap:14px;border-bottom:1px solid var(--ink);padding-bottom:8px;margin-bottom:20px}
.step{font-family:'IBM Plex Mono',monospace;font-size:11px;font-weight:600;color:var(--paper);background:var(--ink);
  padding:3px 8px;letter-spacing:.06em;flex:none}
h2{font-family:'Gowun Batang',serif;font-size:clamp(17px,3vw,21px);font-weight:700;letter-spacing:-.01em;line-height:1.4}
h3{font-size:14px;font-weight:700;margin:26px 0 10px;color:var(--ink-soft);letter-spacing:.02em}
p{margin:12px 0}
.lead{font-size:14.5px;color:var(--ink-soft)}

/* tables */
.scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:16px -2px}
table{border-collapse:collapse;width:100%;font-size:12.5px;min-width:520px}
th,td{padding:7px 9px;border-bottom:1px solid var(--rule);text-align:left;vertical-align:top}
thead th{background:var(--ledger);font-size:11px;font-weight:600;letter-spacing:.03em;color:var(--ink);
  border-bottom:1px solid var(--ink);white-space:nowrap}
td.r,th.r{text-align:right}
td.c,th.c{text-align:center}
tbody tr:nth-child(even){background:rgba(220,228,227,.32)}
tfoot td{background:var(--ink);color:var(--paper);font-weight:600;border:0}
.ok{color:var(--ok);font-weight:700}

/* accumulation ladder */
.ladder{border-left:2px solid var(--rule);margin:22px 0 8px;padding-left:0}
.rung{display:grid;grid-template-columns:1fr auto;gap:6px 14px;align-items:baseline;
  padding:9px 0 9px 18px;position:relative;border-bottom:1px dotted var(--rule)}
.rung::before{content:"";position:absolute;left:-5px;top:18px;width:8px;height:8px;background:var(--paper);
  border:2px solid var(--rule);border-radius:50%}
.rung .lbl{font-size:12.5px;color:var(--ink-soft)}
.rung .op{font-family:'IBM Plex Mono',monospace;font-size:12px;color:var(--ink-soft)}
.rung .run{font-family:'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums;font-size:14px;font-weight:500;text-align:right;white-space:nowrap}
.rung.new{background:rgba(31,92,139,.07);border-bottom:1px dotted var(--add)}
.rung.new::before{border-color:var(--add);background:var(--add)}
.rung.new .lbl,.rung.new .op{color:var(--add)}
.rung.new .run{color:var(--add);font-weight:600}
.rung.total{border-bottom:2px solid var(--ink);padding-top:14px}
.rung.total::before{border-color:var(--seal);background:var(--seal)}
.rung.total .run{font-size:17px;font-weight:600}
.rung.total .lbl{color:var(--ink);font-weight:700}
.seal{display:inline-block;border:1.5px solid var(--seal);color:var(--seal);font-size:10.5px;font-weight:700;
  padding:1px 6px;letter-spacing:.08em;margin-left:8px;vertical-align:middle;transform:rotate(-2deg)}

/* formula block */
.calc{background:var(--ink);color:#DCE7E5;font-family:'IBM Plex Mono',monospace;font-size:12.5px;line-height:2;
  padding:16px 18px;overflow-x:auto;font-variant-numeric:tabular-nums;margin:16px 0}
.calc b{color:var(--mark);font-weight:600}
.calc .cm{color:#7E96A2}

/* callout & lists */
.note{border-left:3px solid var(--seal);background:rgba(176,32,46,.05);padding:12px 16px;margin:20px 0;font-size:13.5px}
.note strong{color:var(--seal)}
.rule-list{list-style:none;counter-reset:r;margin:14px 0}
.rule-list li{counter-increment:r;position:relative;padding-left:34px;margin:10px 0;font-size:13.5px}
.rule-list li::before{content:counter(r);position:absolute;left:0;top:2px;font-family:'IBM Plex Mono',monospace;
  font-size:11px;font-weight:600;border:1px solid var(--ink);width:20px;height:20px;display:grid;place-items:center}

/* glossary cards */
.term{border:1px solid var(--rule);background:rgba(255,255,255,.6);padding:16px 18px;margin:14px 0}
.term-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:10px;border-bottom:1px dotted var(--rule);padding-bottom:10px;margin-bottom:10px}
.term-word{font-family:'Gowun Batang',serif;font-size:19px;font-weight:700}
.hanja{display:inline-flex;gap:4px}
.hj{display:inline-grid;place-items:center;text-align:center;border:1px solid var(--ink);padding:2px 7px;min-width:44px}
.hj b{font-family:'Gowun Batang',serif;font-size:16px;font-weight:700;line-height:1.2}
.hj span{font-size:10px;color:var(--ink-soft);line-height:1.3;white-space:nowrap}
.term-eng{font-family:'IBM Plex Mono',monospace;font-size:11px;color:var(--ink-soft);letter-spacing:.04em;margin-left:auto}
.term-body{font-size:13.5px}
.term-body .eq{font-family:'IBM Plex Mono',monospace;font-size:12px;background:var(--ledger);padding:2px 6px;font-variant-numeric:tabular-nums}
.deal{margin-top:8px;padding:8px 12px;background:rgba(31,92,139,.06);border-left:3px solid var(--add);font-size:12.5px}
.deal b{color:var(--add)}

/* timeline */
.tl{margin:20px 0;border-left:2px solid var(--rule);padding-left:0}
.tl-item{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;padding:8px 0 8px 18px;position:relative;border-bottom:1px dotted var(--rule)}
.tl-item::before{content:"";position:absolute;left:-5px;top:16px;width:8px;height:8px;background:var(--paper);border:2px solid var(--rule);border-radius:50%}
.tl-item.hot::before{border-color:var(--seal);background:var(--seal)}
.tl-date{font-family:'IBM Plex Mono',monospace;font-size:12px;color:var(--ink-soft);white-space:nowrap;padding-top:2px}
.tl-item .what{font-size:13px}

/* worksheet */
.ws{counter-reset:q}
.q{counter-increment:q;position:relative;padding:12px 0 12px 40px;border-bottom:1px dotted var(--rule);font-size:14px;line-height:2.1}
.q::before{content:"Q" counter(q);position:absolute;left:0;top:14px;font-family:'IBM Plex Mono',monospace;
  font-size:11px;font-weight:600;border:1.5px solid var(--ink);padding:1px 5px}
.blank{display:inline-block;min-width:88px;border-bottom:2px solid var(--ink);height:1.2em;vertical-align:-2px;margin:0 3px;
  background:linear-gradient(180deg,transparent 65%,rgba(245,224,107,.45) 65%)}
.blank.w{min-width:130px}
.blank.s{min-width:56px}
.answers{margin-top:34px;border-top:2px solid var(--ink);padding-top:12px}
.ans-body{transform:rotate(180deg);font-size:11px;color:var(--ink-soft);line-height:1.9;font-family:'IBM Plex Mono',monospace}

.delta{color:var(--add);font-weight:600}
footer{margin-top:48px;border-top:1px solid var(--rule);padding-top:14px;font-size:11.5px;color:var(--ink-soft);
  font-family:'IBM Plex Mono',monospace;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}

@media (max-width:560px){
  body{background-image:none}
  .rung{grid-template-columns:1fr;gap:2px}
  .rung .run{text-align:left}
  .term-eng{margin-left:0;width:100%}
}
@media (prefers-reduced-motion:no-preference){
  .rung{animation:rise .5s ease-out both}
  @keyframes rise{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
}

/* ── A4 print ─────────────────────────────── */
@page{size:A4;margin:13mm 12mm}
body{-webkit-print-color-adjust:exact;print-color-adjust:exact}
.fig{break-inside:avoid;page-break-inside:avoid}

@media print{
  html,body{background:#fff;background-image:none;padding:0;margin:0;font-size:10.2pt;line-height:1.6}
  .sheet{max-width:none;width:100%;margin:0;padding:0;border:0;box-shadow:none;background:#fff}
  .fig,table,.term,.tl-item,.q,.rung,.meta,figure,img,svg{break-inside:avoid;page-break-inside:avoid}
  .scroll{overflow:visible}
  table{min-width:0;width:100%;font-size:8.6pt}
  thead{display:table-header-group}
  tfoot{display:table-footer-group}
  tr,td,th{break-inside:avoid;page-break-inside:avoid}
  section{break-inside:auto;page-break-inside:auto;margin-top:9mm}
  .sechead,h1,h2,h3{break-after:avoid;page-break-after:avoid;break-inside:avoid}
  p,li{orphans:3;widows:3}
  .ws,.tl,.ladder{break-inside:auto;page-break-inside:auto}
  #worksheet{break-before:page;page-break-before:always}
  .step{background:var(--ink)!important;color:#fff!important}
  .calc{background:var(--ink)!important;color:#E4EDEB!important}
  tfoot td{background:var(--ink)!important;color:#fff!important}
  thead th{background:var(--ledger)!important}
  tbody tr:nth-child(even){background:rgba(220,228,227,.45)!important}
  .mark{background:var(--mark)!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .blank{background:linear-gradient(180deg,transparent 65%,rgba(245,224,107,.5) 65%)!important}
  .term-body .eq{background:var(--ledger)!important}
  .deal{background:rgba(31,92,139,.08)!important;border-left-color:var(--add)!important}
  .deal b{color:var(--add)!important}
  .note{background:rgba(176,32,46,.06)!important;border-left-color:var(--seal)!important}
  .note strong{color:var(--seal)!important}
  .rung.new{background:rgba(31,92,139,.10)!important}
  .seal{border-color:var(--seal)!important;color:var(--seal)!important}
  .ok{color:var(--ok)!important}
  .delta{color:var(--add)!important}
  .rung{animation:none!important;opacity:1!important;transform:none!important}
  a[href]::after{content:""}
}

