from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

SOURCE = Path('C:/Users/djliz/.codex')
ROOT = Path('C:/Users/djliz/study_certificate')
DEST = ROOT / 'codex_backup/.codex'
WORK = Path(__file__).resolve().parent
REDACTED = '[REDACTED_FOR_PUBLIC_BACKUP]'
KEYS = re.compile(r'(?i)^(?:api[_-]?key|openai_api_key|access[_-]?token|refresh[_-]?token|id[_-]?token|auth[_-]?token|bearer[_-]?token|client[_-]?secret|password|passwd|authorization|proxy-authorization|cookie|set-cookie|secret|ownership_token|token)$')
PATTERNS = {
    'github_token': re.compile(r'(?<![A-Za-z0-9_])(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{60,})'),
    'openai_key': re.compile(r'(?<![A-Za-z0-9_-])sk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{40,}'),
    'aws_key': re.compile(r'(?<![A-Za-z0-9])(?:AKIA|ASIA)[A-Z0-9]{16}(?![A-Za-z0-9])'),
    'slack_token': re.compile(r'(?<![A-Za-z0-9])xox[baprs]-[0-9A-Za-z-]{20,}'),
    'jwt': re.compile(r'eyJ[A-Za-z0-9_-]{12,}\.[A-Za-z0-9_-]{12,}\.[A-Za-z0-9_-]{12,}'),
    'private_key': re.compile(r'-----BEGIN (?:RSA |EC |OPENSSH |DSA |ENCRYPTED )?PRIVATE KEY-----[A-Za-z0-9+/=\s\\n-]+?-----END (?:RSA |EC |OPENSSH |DSA |ENCRYPTED )?PRIVATE KEY-----'),
    'bearer': re.compile(r'(?i)\b(?:Bearer|Basic)\s+[A-Za-z0-9_./+=-]{24,}'),
    'url_credential': re.compile(r'(?i)(?<=https://)[^\s/:<>"\x27]+:[^\s/@<>"\x27]+@'),
}
ASSIGNMENT = re.compile(r'''(?im)(\b(?:api[_-]?key|openai_api_key|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|passwd)\b\s*[:=]\s*)(["'])([^"'\r\n]{8,})(\2)''')
QUERY = re.compile(r'(?i)([?&](?:access_token|api_key|token|sig|x-amz-signature|x-amz-security-token)=)[^&\s"<>]+')
COUNTS: Counter[str] = Counter()
KNOWN_SECRETS: list[str] = []


def collect_secrets(value: object, key: str = '') -> None:
    """Keep known authentication strings in memory solely to remove their copies."""
    if isinstance(value, dict):
        for name, child in value.items():
            collect_secrets(child, name)
    elif isinstance(value, list):
        for child in value:
            collect_secrets(child, key)
    elif isinstance(value, str) and KEYS.fullmatch(key) and len(value) > 12:
        KNOWN_SECRETS.append(value)


def clean_text(text: str) -> str:
    """Redact credential-shaped strings without printing their values."""
    for secret in KNOWN_SECRETS:
        if secret in text:
            COUNTS['known_authentication_value'] += text.count(secret)
            text = text.replace(secret, REDACTED)
    for name, pattern in PATTERNS.items():
        text, count = pattern.subn(REDACTED, text)
        COUNTS[name] += count
    text, count = ASSIGNMENT.subn(lambda match: match[1] + match[2] + REDACTED + match[4], text)
    COUNTS['credential_assignment'] += count
    text, count = QUERY.subn(lambda match: match[1] + REDACTED, text)
    COUNTS['signed_url_credential'] += count
    return text


def clean_value(value: object, key: str = '') -> object:
    """Redact structured secret fields and any secrets embedded in prose."""
    if isinstance(value, dict):
        return {name: clean_value(child, name) for name, child in value.items()}
    if isinstance(value, list):
        return [clean_value(child, key) for child in value]
    if isinstance(value, str):
        if KEYS.fullmatch(key) and value and value != REDACTED:
            COUNTS['credential_field'] += 1
            return REDACTED
