            else:
                cleaned = clean_value(nested)
                if cleaned != nested:
                    return json.dumps(cleaned, ensure_ascii=False, separators=(',', ':'))
        return clean_text(value)
    return value


def exclusion(relative: Path) -> str | None:
    """Exclude authentication material and live transient state, not settings."""
    if relative.parts[0] in {'.tmp', 'tmp', 'cache', 'app-server-control', 'thread-writer-locks', 'tui-thread-reference-capabilities'}:
        return 'transient_cache_or_runtime_control'
    if '.git' in relative.parts or '.remote-plugin-install-staging' in relative.parts:
        return 'temporary_plugin_checkout'
    if relative.name in {'auth.json', 'cap_sid', 'installation_id'}:
        return 'authentication_or_live_instance_identifier'
    if relative.name.endswith(('-wal', '-shm')):
        return 'incorporated_into_consistent_sqlite_snapshot'
    if relative.name.endswith(('.lock', '.sock', '.pid')):
        return 'live_lock_socket_or_process_id'
    return None


def quote_identifier(value: str) -> str:
    """Quote a SQLite table or column name."""
    return '"' + value.replace('"', '""') + '"'


def snapshot_sqlite(source: Path, destination: Path) -> dict:
    """Use SQLite backup, redact cell values, and remove obsolete page contents."""
    started = time.monotonic()
    source_connection = sqlite3.connect(source.as_uri() + '?mode=ro', uri=True, timeout=10)
    target_connection = sqlite3.connect(destination)

    def progress(status: int, remaining: int, total: int) -> None:
        if time.monotonic() - started > 120:
            raise TimeoutError('SQLite snapshot did not finish within 120 seconds: ' + source.name)

    source_connection.backup(target_connection, pages=1024, progress=progress, sleep=0.05)
    source_connection.close()
    target_connection.execute('PRAGMA secure_delete=ON')
    tables = target_connection.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").fetchall()
    cells_changed = 0
    table_counts = {}
    for (table,) in tables:
        name = quote_identifier(table)
        info = target_connection.execute(f'PRAGMA table_info({name})').fetchall()
        columns = [row[1] for row in info]
        try:
            reader = target_connection.execute(f'SELECT rowid, * FROM {name}')
            rowid = True
        except sqlite3.OperationalError:
            reader = target_connection.execute(f'SELECT * FROM {name}')
            rowid = False
        total = 0
        for row in reader:
            total += 1
            values = row[1:] if rowid else row
            changes = {}
            for column, value in zip(columns, values, strict=True):
                if isinstance(value, str):
                    cleaned = clean_value(value, column)
                    if cleaned != value:
                        changes[column] = cleaned
                elif isinstance(value, bytes) and value:
                    try:
                        decoded = value.decode('utf-8')
                    except UnicodeDecodeError:
                        continue
                    cleaned = clean_text(decoded)
                    if cleaned != decoded:
                        changes[column] = cleaned.encode('utf-8')
            if changes:
                assignments = ','.join(quote_identifier(column) + '=?' for column in changes)
                params = list(changes.values())
                if rowid:
                    where = 'rowid=?'
                    params.append(row[0])
                else:
                    primary = [column[1] for column in sorted(info, key=lambda item: item[5]) if column[5]]
                    if not primary:
                        raise RuntimeError('No safe row identifier in ' + table)
                    where = ' AND '.join(quote_identifier(column) + '=?' for column in primary)
                    params.extend(values[columns.index(column)] for column in primary)
                target_connection.execute(f'UPDATE {name} SET {assignments} WHERE {where}', params)
                cells_changed += len(changes)
        table_counts[table] = total
    target_connection.commit()
    target_connection.execute('PRAGMA wal_checkpoint(TRUNCATE)')
    target_connection.execute('PRAGMA journal_mode=DELETE')
    target_connection.execute('VACUUM')
    integrity = target_connection.execute('PRAGMA integrity_check').fetchone()[0]
    target_connection.close()
    if integrity != 'ok':
        raise RuntimeError('Invalid database snapshot: ' + source.name)
    return {'tables': table_counts, 'changed_cells': cells_changed, 'integrity_check': integrity}


def copy_file(source: Path, destination: Path) -> dict:
    """Copy the current file snapshot, retaining complete JSONL records only."""
    destination.parent.mkdir(parents=True, exist_ok=True)
