"""Commit and verify the prepared public Codex snapshot."""

import hashlib
import json
import sys
import urllib.request
from pathlib import Path

import publish

BACKUP = publish.ROOT / 'codex_backup'


def prepare() -> None:
    """Check the manifest, add large-file tracking, and commit the complete backup."""
    manifest = json.loads((BACKUP / 'BACKUP_MANIFEST.json').read_text(encoding='utf-8'))
    if 'additional_public_audit' not in manifest:
        raise RuntimeError('Public backup audit has not completed.')
    source_paths = {record['path'] for record in manifest['files']}
    actual_paths = {path.relative_to(BACKUP / '.codex').as_posix() for path in (BACKUP / '.codex').rglob('*') if path.is_file()}
    if source_paths != actual_paths or 'auth.json' in actual_paths or 'cap_sid' in actual_paths:
        raise RuntimeError('Unexpected file list or authentication file present.')
    for required in ['config.toml', 'AGENTS.md', 'memories_1.sqlite', 'history.jsonl', 'state_5.sqlite', 'thread_history_1.sqlite']:
        if required not in source_paths:
            raise RuntimeError('Required Codex data missing: ' + required)
    large = []
    for record in manifest['files']:
        path = BACKUP / '.codex' / record['path']
        with path.open('rb') as stream:
            if hashlib.file_digest(stream, 'sha256').hexdigest() != record['sha256']:
                raise RuntimeError('Snapshot checksum changed: ' + record['path'])
        if record['bytes'] > 50 * 1024 * 1024:
            large.append(record)
            publish.git('lfs', 'track', '--filename', path.relative_to(publish.ROOT).as_posix())
    readme = publish.ROOT / 'README.md'
    text = readme.read_text(encoding='utf-8')
    if '## Codex 공개용 백업' not in text:
        text += '\n## Codex 공개용 백업\n\n설정·메모리·대화 기록·스킬·플러그인·실행 파일의 공개용 스냅샷은 [codex_backup](codex_backup/README.md)에 있습니다. 인증정보와 임시 실행 상태는 제외했습니다. 세부 처리 내역은 [Codex 백업 매니페스트](codex_backup/BACKUP_MANIFEST.json)를 확인하세요.\n'
        readme.write_text(text, encoding='utf-8')
    backup_readme = BACKUP / 'README.md'
    text = backup_readme.read_text(encoding='utf-8')
    text += f"\n## 최종 검증\n\n추가 공개 검사를 마쳤으며, 최종 파일 수는 {manifest['file_count']:,}개, 전체 크기는 {manifest['total_bytes']:,}바이트입니다. 인증정보 패턴 치환 내역이 있는 파일은 {manifest['files_redacted']:,}개입니다. 대용량 파일 {len(large)}개는 Git LFS로 보관했습니다.\n"
    backup_readme.write_text(text, encoding='utf-8')
    print(json.dumps({'stage': 'staging_codex', 'snapshot_files': manifest['file_count'], 'lfs_paths': len(large)}, ensure_ascii=False), flush=True)
    publish.git('add', '--force', '--', '.gitattributes', 'README.md', 'codex_backup', timeout=900)
    staged = {}
    for entry in publish.git('ls-files', '--stage', '-z', '--', 'codex_backup').split(b'\0'):
        if entry:
            meta, name = entry.split(b'\t', 1)
            staged[name.decode()] = meta.decode().split()[1]
    if len(staged) != manifest['file_count'] + 2:
        raise RuntimeError('Codex staging count mismatch.')
    for record in manifest['files']:
        relative = 'codex_backup/.codex/' + record['path']
        if record in large:
            pointer = publish.git('show', ':' + relative).decode()
            if f"oid sha256:{record['sha256']}\n" not in pointer:
                raise RuntimeError('LFS pointer does not match sanitized data: ' + relative)
        else:
            digest = hashlib.sha1(f"blob {record['bytes']}\0".encode())
            with (publish.ROOT / relative).open('rb') as stream:
                for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                    digest.update(chunk)
            if staged[relative] != digest.hexdigest():
                raise RuntimeError('Staged backup differs from the sanitized copy: ' + relative)
    publish.git('commit', '-q', '-m', 'Back up Codex settings, memories, sessions and tools with credentials redacted', timeout=900)
    state = json.loads(publish.STATE_PATH.read_text(encoding='utf-8'))
    state['codex_backup'] = {'files': manifest['file_count'], 'bytes': manifest['total_bytes'], 'redacted_files': manifest['files_redacted'], 'lfs_paths': len(large), 'lfs_unique_objects': len({record['sha256'] for record in large}), 'path': 'codex_backup/.codex'}
    state['commit'] = publish.git('rev-parse', 'HEAD').decode().strip()
    state['stage'] = 'codex_committed'
    publish.save(state)
    print(json.dumps(state['codex_backup'] | {'commit': state['commit']}, ensure_ascii=False), flush=True)


def verify() -> None:
    """Verify new LFS objects in addition to all remote Git blobs."""
    publish.verify()
    state = json.loads(publish.STATE_PATH.read_text(encoding='utf-8'))
    manifest = json.loads((BACKUP / 'BACKUP_MANIFEST.json').read_text(encoding='utf-8'))
    objects = {record['sha256']: {'oid': record['sha256'], 'size': record['bytes']} for record in manifest['files'] if record['bytes'] > 50 * 1024 * 1024}
    request = urllib.request.Request(
        'https://github.com/' + state['repository'] + '.git/info/lfs/objects/batch',
        data=json.dumps({'operation': 'download', 'transfers': ['basic'], 'objects': list(objects.values())}).encode(),
        headers={'Authorization': 'Bearer ' + publish.token(), 'Accept': 'application/vnd.git-lfs+json', 'Content-Type': 'application/vnd.git-lfs+json'},
    )
    with urllib.request.urlopen(request, timeout=45) as response:
        result = json.load(response)
    if len(result['objects']) != len(objects) or any('error' in item or 'download' not in item.get('actions', {}) for item in result['objects']):
        raise RuntimeError('A Codex LFS object is unavailable.')
    state['codex_backup']['verified_remote_lfs_objects'] = len(objects)
    state['tracked_files'] = state['remote_files']
    state['stage'] = 'codex_verified'
    publish.save(state)
    print(json.dumps(state, ensure_ascii=False), flush=True)


if __name__ == '__main__':
    {'prepare': prepare, 'verify': verify}[sys.argv[1]]()

